begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local s1.tap='on';
select no_plan();
\ir s4_fixture.sql
create function pg_temp.s4_state_of(c text) returns text language sql as $$ select pg_temp.sqlstate_of(c) $$;
create function pg_temp.s4_candidate(label text) returns uuid language sql as $$ select public.add_voting_item('24000000-0000-4000-8000-000000000001','menu',label) $$;
grant execute on function pg_temp.s4_candidate(text) to authenticated;
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of($q$select pg_temp.s4_candidate('Early')$q$)='S4003','restaurant candidates require place stage');
insert into s4_data values('time-candidate',to_jsonb(public.add_voting_item('24000000-0000-4000-8000-000000000001','time','Legacy time')));
select pg_temp.check(pg_temp.sqlstate_of($q$select public.confirm_room_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='time-candidate'))$q$)='S4010','legacy time label cannot set structured time');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.advance_room_stage('24000000-0000-4000-8000-000000000001','confirmed')$q$)='S4003','generic stage cannot skip place');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.advance_room_stage('24000000-0000-4000-8000-000000000001','settling')$q$)='S4003','generic stage cannot enter settlement');
insert into s4_data values('submit-revision',to_jsonb(pg_temp.s4_revision('24000000-0000-4000-8000-000000000001')));
insert into s4_data values('submit-result',public.submit_room_availability_v1('24000000-0000-4000-8000-000000000001',array(select jsonb_array_elements_text(v) from s4_data where k='slots'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),'64000000-0000-4000-8000-000000000011'));
select pg_temp.check(public.submit_room_availability_v1('24000000-0000-4000-8000-000000000001',array(select jsonb_array_elements_text(v) from s4_data where k='slots'),(select (v#>>'{}')::bigint from s4_data where k='submit-revision'),'64000000-0000-4000-8000-000000000011')->>'outcome'='replayed','submission retries replay without bump');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.submit_room_availability_v1('24000000-0000-4000-8000-000000000001','{}',(select (v#>>'{}')::bigint from s4_data where k='submit-revision'),'64000000-0000-4000-8000-000000000011')$q$)='S1007','same request with different payload is a conflict');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.submit_room_availability_v1('24000000-0000-4000-8000-000000000001',array(select jsonb_array_elements_text(v) from s4_data where k='slots'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),'64000000-0000-4000-8000-000000000011')$q$)='S1007','same request with changed expected revision is a conflict');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.select_room_meeting_time_v1('24000000-0000-4000-8000-000000000001',null,0,'64000000-0000-4000-8000-000000000011')$q$)='S1007','same request across operations is a conflict before CAS');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.submit_room_availability_v1('24000000-0000-4000-8000-000000000001','{}',0,gen_random_uuid())$q$)='S4005','fresh request with stale revision fails CAS');
insert into s4_data values('stable-revision',to_jsonb(pg_temp.s4_revision('24000000-0000-4000-8000-000000000001')));
select pg_temp.s4_submit('24000000-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.s4_revision('24000000-0000-4000-8000-000000000001')=(select (v#>>'{}')::bigint from s4_data where k='stable-revision'),'same schedule under new request does not bump revision');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.s4_submit('24000000-0000-4000-8000-000000000001');
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(public.advance_room_stage('24000000-0000-4000-8000-000000000001','place')='place','legacy place wrapper requires and accepts complete roster');
insert into s4_data values('m1',to_jsonb(pg_temp.s4_candidate('First restaurant'))),('m2',to_jsonb(pg_temp.s4_candidate('Second restaurant')));
select pg_temp.check(pg_temp.sqlstate_of($q$select pg_temp.s4_candidate(' first RESTAURANT ')$q$)='23505','trimmed case-insensitive duplicate is rejected');
select pg_temp.check(pg_temp.sqlstate_of($q$select pg_temp.s4_candidate('   ')$q$)='S4002','blank label is rejected');
select pg_temp.check(pg_temp.sqlstate_of($q$select pg_temp.s4_candidate(repeat('한',121))$q$)='S4002','121 Unicode characters are rejected');
select pg_temp.check(pg_temp.s4_candidate(repeat('한',120)) is not null,'120 Unicode characters are accepted');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.confirm_room_appointment_v1('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid())$q$)='S4007','final confirmation requires structured time even in place');
select public.select_room_meeting_time_v1('24000000-0000-4000-8000-000000000001',(select v from s4_data where k='time'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid());
select pg_temp.check(pg_temp.sqlstate_of($q$select public.confirm_room_appointment_v1('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid())$q$)='S4008','no-vote arbitrary owner confirmation is rejected');
select public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'));
select pg_temp.check(pg_temp.sqlstate_of($q$select public.confirm_room_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'))$q$)='S4008','one of two actual members is not strict majority');
reset role;
update public.participants set voted_items=jsonb_build_array((select v#>>'{}' from s4_data where k='m1')) where room_id='24000000-0000-4000-8000-000000000001' and profile_id is null;
set local role authenticated;
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->'voting'->>'leading_votes'='1','NULL profile fake votes never count');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'));
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m2'));
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m2'));
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->'voting'->>'leading_item_id'=(select v#>>'{}' from s4_data where k='m1'),'equal-vote tie uses original candidate array order');
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->>'stage'='place','all eligible votes still never auto-confirm');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.confirm_room_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m2'))$q$)='S4008','tied but later candidate cannot be confirmed');
reset role;
insert into public.participants(room_id,profile_id,name) values('24000000-0000-4000-8000-000000000001','10000003-0000-4000-8000-000000000003','S4 third');
set local role authenticated;
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->'voting'->>'required_votes'='2','three eligible members require two votes');
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->'availability'->>'submitted_count'='2','late join is unsubmitted without changing selected time');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.add_voting_item('24000000-0000-4000-8000-000000000001','time','Wrong stage')$q$)='S4003','time label candidates cannot mutate place');
select pg_temp.s4_candidate('Capacity '||i) from generate_series(4,30) i;
select pg_temp.check(pg_temp.sqlstate_of($q$select pg_temp.s4_candidate('Thirty first')$q$)='S4001','31st menu candidate fails with candidate limit');
select pg_temp.check(pg_temp.sqlstate_of($q$select pg_temp.s4_candidate(' ')$q$)='S4002','label validation precedes full-list limit');
select pg_temp.check(public.remove_voting_item('24000000-0000-4000-8000-000000000001','ffffffff-ffff-4fff-8fff-ffffffffffff')=false,'missing candidate removal is a no-op');
-- Failure injected after the room UPDATE, before message insertion: the full RPC must roll back.
reset role;
create function pg_temp.s4_fail_event() returns trigger language plpgsql as $$ begin if new.event_key like 'appointment-confirmed:%' then raise exception 'synthetic event failure' using errcode='P4999'; end if; return new; end; $$;
create trigger s4_synthetic_fail_event before insert on public.messages for each row execute function pg_temp.s4_fail_event();
insert into s4_data values('atomic-revision',to_jsonb((select s4_revision from public.rooms where id='24000000-0000-4000-8000-000000000001')));
set local role authenticated;
select pg_temp.check(pg_temp.sqlstate_of($q$select public.confirm_room_appointment_v1('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),'64000000-0000-4000-8000-000000000021')$q$)='P4999','injected event failure reaches the post-update atomic boundary');
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->>'stage'='place' and pg_temp.s4_revision('24000000-0000-4000-8000-000000000001')=(select (v#>>'{}')::bigint from s4_data where k='atomic-revision'),'event failure rolls back canonical room and revision');
reset role;
select pg_temp.check(not exists(select 1 from private.s4_requests where request_id='64000000-0000-4000-8000-000000000021') and not exists(select 1 from public.messages where event_key like 'appointment-confirmed:%'),'event failure leaves neither ledger nor message');
drop trigger s4_synthetic_fail_event on public.messages;
set local role authenticated;
select public.confirm_room_appointment_v1('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),'64000000-0000-4000-8000-000000000021');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.confirm_room_appointment_v1('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m2'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid())$q$)='S4009','different restaurant cannot replace confirmed appointment');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'))$q$)='S4003','final confirmation closes vote mutation');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.remove_voting_item('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'))$q$)='S4003','final confirmation closes candidate deletion');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.select_room_meeting_time_v1('24000000-0000-4000-8000-000000000001',(select v from s4_data where k='time'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid())$q$)='S4003','final confirmation closes selected time mutation');
-- Keep the NULL-profile display fixture: the corrected settlement core excludes it.
insert into s4_data values('bill',to_jsonb(public.create_room_settlement_v2('24000000-0000-4000-8000-000000000001','S4 regression bill',3000,'Synthetic bank','0000','Synthetic A')));
select pg_temp.check(public.advance_room_stage('24000000-0000-4000-8000-000000000001','confirmed')='settling','legacy follow-up never rewinds settlement');
select public.confirm_room_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'));
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->>'stage'='settling','same restaurant natural retry preserves settling');
select public.set_settlement_completed(id,true) from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='bill');
select pg_temp.check(public.advance_room_stage('24000000-0000-4000-8000-000000000001','confirmed')='done','legacy follow-up never rewinds done');
select public.confirm_room_appointment_v1('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='m1'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid());
select pg_temp.check(public.get_settlement_payment_details((select (v#>>'{}')::uuid from s4_data where k='bill'))->>'status'='completed','natural retry never reopens closed account');
reset role;
select pg_temp.check((select count(*)=1 from public.messages where event_key='appointment-confirmed:24000000-0000-4000-8000-000000000001'),'atomic and natural retries emit exactly one appointment event');
select pg_temp.check((select meeting_starts_at=((select v->>'starts_at' from s4_data where k='time')::timestamptz) and appointment_confirmed_at is not null from public.rooms where id='24000000-0000-4000-8000-000000000001'),'financial progress preserves structured time and owner confirmation');
select * from finish();
rollback;
